using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;using System.ComponentModel;using System.Runtime.Serialization;
namespace CircuitoStudio {
[DataContract]public enum MotorStarterKind{[EnumMember] ContactorOverload,[EnumMember] ManualSwitchOverload,[EnumMember] ManualMotorBreaker}
[DataContract]public enum OverloadConnection{[EnumMember] Unknown,[EnumMember] InLine,[EnumMember] InsideDelta}
[DataContract]public enum StarterProtectionKind{[EnumMember] None,[EnumMember] PrimaryBreaker,[EnumMember] SelectedFuse}
[DataContract]public sealed class MotorStarterRating {
[DataMember]public MotorStarterKind Kind{get;set;}[DataMember]public string Manufacturer{get;set;}[DataMember]public string Reference{get;set;}[DataMember]public string ControllerReference{get;set;}[DataMember]public string Service{get;set;}[DataMember]public double VoltageV{get;set;}[DataMember]public double FrequencyHz{get;set;}[DataMember]public PoleLayout Poles{get;set;}[DataMember]public double RatedMotorA{get;set;}[DataMember]public string OverloadReference{get;set;}[DataMember]public string TripClass{get;set;}[DataMember]public double ThermalMinimumA{get;set;}[DataMember]public double ThermalMaximumA{get;set;}[DataMember]public double ThermalSettingA{get;set;}[DataMember]public OverloadConnection OverloadConnection{get;set;}[DataMember]public double StandaloneBreakingKA{get;set;}[DataMember]public double ConditionalKA{get;set;}[DataMember]public StarterProtectionKind ProtectionKind{get;set;}[DataMember]public string RequiredProtectionConfiguration{get;set;}[DataMember]public string CoordinationType{get;set;}[DataMember]public string AssemblyDocument{get;set;}[DataMember]public double ControlVoltageV{get;set;}[DataMember]public ControlSupply ControlSupply{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string Conditions{get;set;}
public MotorStarterRating(){Manufacturer=Reference=ControllerReference=Service=OverloadReference=TripClass=RequiredProtectionConfiguration=CoordinationType=AssemblyDocument=Source=DataVersion=Conditions="";}
public MotorStarterRating Copy(){return (MotorStarterRating)MemberwiseClone();}
public void Validate(){if(!Enum.IsDefined(typeof(MotorStarterKind),Kind)||!Enum.IsDefined(typeof(PoleLayout),Poles)||!Enum.IsDefined(typeof(OverloadConnection),OverloadConnection)||!Enum.IsDefined(typeof(StarterProtectionKind),ProtectionKind)||!Enum.IsDefined(typeof(ControlSupply),ControlSupply))throw new InvalidDataException("Tipo/polos/ligação/alimentação da partida inválidos.");foreach(string text in new[]{Manufacturer,Reference,ControllerReference,Source,DataVersion,Conditions})if(String.IsNullOrWhiteSpace(text)||text.Length>2000||text.IndexOf('\0')>=0)throw new InvalidDataException("Informe fabricante, referência do conjunto/controlador, fonte, versão e condições (até2000 caracteres).");foreach(string text in new[]{Service,OverloadReference,TripClass,RequiredProtectionConfiguration,CoordinationType,AssemblyDocument})if(text==null||text.Length>2000||text.IndexOf('\0')>=0)throw new InvalidDataException("Referência de partida inválida.");Project.Range(VoltageV,1,1e6,"tensão da partida");Project.Range(FrequencyHz,1,1000,"frequência da partida");Project.Range(RatedMotorA,.001,1e9,"corrente máxima de motor do conjunto");foreach(double x in new[]{ThermalMinimumA,ThermalMaximumA,ThermalSettingA,StandaloneBreakingKA,ConditionalKA,ControlVoltageV})Project.Range(x,0,1e12,"ajuste/capacidade da partida");if(ThermalMinimumA>0&&ThermalMaximumA>0&&ThermalMaximumA<ThermalMinimumA)throw new InvalidDataException("Faixa do relé térmico invertida.");if(Kind!=MotorStarterKind.ManualMotorBreaker&&StandaloneBreakingKA!=0)throw new InvalidDataException("Contator/manobra com térmico não recebe capacidade própria de interrupção de curto.");if(ConditionalKA==0){if(ProtectionKind!=StarterProtectionKind.None||RequiredProtectionConfiguration!="")throw new InvalidDataException("Capacidade condicional, tipo e configuração da proteção devem ser informados juntos.");}else if(ProtectionKind==StarterProtectionKind.None||RequiredProtectionConfiguration.Length!=64||RequiredProtectionConfiguration.Any(x=>!Uri.IsHexDigit(x))||String.IsNullOrWhiteSpace(AssemblyDocument))throw new InvalidDataException("Associação de curto exige proteção exata e documento.");if(Kind!=MotorStarterKind.ContactorOverload&&(ControlVoltageV!=0||ControlSupply!=ControlSupply.NotApplicable))throw new InvalidDataException("Partida manual não usa os campos de bobina do contator.");if((ControlVoltageV==0)!=(ControlSupply==ControlSupply.NotApplicable))throw new InvalidDataException("Informe tensão e tipo de alimentação da bobina juntos.");}
}
[DataContract]public sealed class MotorStarterBinding {
[DataMember]public string Engine{get;set;}[DataMember]public MotorStarterRating Rating{get;set;}[DataMember]public double MotorRatedA{get;set;}[DataMember]public string MotorNameplateSource{get;set;}[DataMember]public string RequiredService{get;set;}[DataMember]public string RequiredTripClass{get;set;}[DataMember]public string RequiredCoordinationType{get;set;}[DataMember]public PoleLayout RequiredPoles{get;set;}[DataMember]public double ControlVoltageV{get;set;}[DataMember]public ControlSupply ControlSupply{get;set;}
public void Validate(){if(Engine!=MotorStarterSelection.EngineId||Rating==null||!Enum.IsDefined(typeof(PoleLayout),RequiredPoles)||!Enum.IsDefined(typeof(ControlSupply),ControlSupply))throw new InvalidDataException("Seleção de partida inválida ou revisão desconhecida.");Rating.Validate();foreach(string text in new[]{MotorNameplateSource,RequiredService,RequiredTripClass,RequiredCoordinationType})if(text==null||text.Length>2000||text.IndexOf('\0')>=0)throw new InvalidDataException("Requisito de motor inválido.");Project.Range(MotorRatedA,0,1e9,"corrente de placa do motor");Project.Range(ControlVoltageV,0,1e6,"comando da partida");if((MotorRatedA==0)!=String.IsNullOrWhiteSpace(MotorNameplateSource))throw new InvalidDataException("Informe corrente de placa e sua referência juntas, ou deixe ambas vazias.");if(Rating.Kind!=MotorStarterKind.ContactorOverload&&(ControlVoltageV!=0||ControlSupply!=ControlSupply.NotApplicable))throw new InvalidDataException("Comando de bobina não se aplica à partida manual selecionada.");if((ControlVoltageV==0)!=(ControlSupply==ControlSupply.NotApplicable))throw new InvalidDataException("Informe tensão e tipo do circuito de comando juntos.");}
}
public sealed partial class Circuit{[DataMember(Order=101),Browsable(false)]public MotorStarterBinding MotorStarterSelection{get;set;}}
public sealed class MotorStarterEvaluation{public string Status,Detail;public double NominalCalculatedA;}
public static class MotorStarterSelection {
public const string EngineId="cs-partidas-conjuntos-v1";
public const string Header="Kind;Manufacturer;Reference;ControllerReference;Service;VoltageV;FrequencyHz;Poles;RatedMotorA;OverloadReference;TripClass;ThermalMinimumA;ThermalMaximumA;ThermalSettingA;OverloadConnection;StandaloneBreakingKA;ConditionalKA;ProtectionKind;RequiredProtectionConfiguration;CoordinationType;AssemblyDocument;ControlVoltageV;ControlSupply;Source;DataVersion;Conditions";
public static string ProtectionConfiguration(Circuit c,StarterProtectionKind kind){if(kind==StarterProtectionKind.PrimaryBreaker)return Coordination.ProtectionConfiguration(c);if(kind==StarterProtectionKind.SelectedFuse&&c.SwitchgearSelection!=null&&c.SwitchgearSelection.Rating.IsFuse)return ProtectionResponses.Hash(c.SwitchgearSelection);return "";}
static bool Same(string a,string b){return String.Equals((a??"").Trim(),(b??"").Trim(),StringComparison.OrdinalIgnoreCase);}
public static double NominalCurrent(Circuit c){double q=c.ReactiveKvarOverride??c.PowerKw*Math.Tan(Math.Acos(c.PowerFactor));return 1000*Math.Sqrt(c.PowerKw*c.PowerKw+q*q)/(c.Voltage*(c.Phases==PhaseMode.Trifasico?Math.Sqrt(3):1));}
public static MotorStarterEvaluation Evaluate(Project p,Study study,Circuit c,MotorStarterBinding binding){if(binding==null)return new MotorStarterEvaluation{Status="Pendente",Detail="Conjunto de partida não selecionado."};binding.Validate();var row=study.For(c);if(row==null)throw new InvalidDataException("Circuito fora do projeto.");var r=binding.Rating;bool fail=false,pending=false;double nominal=NominalCurrent(c);var text=new StringBuilder("Motor "+EngineId+". Conjunto "+r.Manufacturer+" / "+r.Reference+"; controlador "+r.ControllerReference+"; relé térmico "+r.OverloadReference+"; serviço "+r.Service+"; classe "+r.TripClass+". Corrente máxima de motor na condição da ficha="+r.RatedMotorA+" A; motor de placa="+binding.MotorRatedA+" A; referência "+binding.MotorNameplateSource+". Corrente nominal calculada sem demanda="+nominal.ToString("G8",CultureInfo.CurrentCulture)+" A; corrente demandada da rede="+row.CurrentA.ToString("G8",CultureInfo.CurrentCulture)+" A. Fonte: "+r.Source+"; versão "+r.DataVersion+"; condições "+r.Conditions+".\r\n");
Compare(text,"Circuito terminal e condição elétrica",c.ChildBoardId==""&&r.Poles==binding.RequiredPoles&&r.VoltageV==c.Voltage&&r.FrequencyHz==p.Frequency&&BreakerSelection.ValidTopology(row,binding.RequiredPoles),"Tensão/frequência/polos exatos; o conjunto não é seleção para um alimentador de quadro.",ref fail,ref pending);Compare(text,"Corrente máxima do conjunto ≥ corrente de placa",binding.MotorRatedA>0?(bool?)(r.RatedMotorA>=binding.MotorRatedA):null,"Não reduzir pela demanda do circuito.",ref fail,ref pending);if(binding.MotorRatedA>0&&nominal>binding.MotorRatedA+1e-9*Math.Max(1,binding.MotorRatedA)){pending=true;text.AppendLine("Pendente: corrente nominal calculada excede a placa declarada; conciliar potência/FP/tensão e dados de placa antes de concluir.");}
Compare(text,"Serviço/categoria exigidos",String.IsNullOrWhiteSpace(r.Service)||String.IsNullOrWhiteSpace(binding.RequiredService)?(bool?)null:Same(r.Service,binding.RequiredService),"Serviço exigido="+binding.RequiredService+"; não inferir equivalência entre AC-3/AC-4 ou regimes.",ref fail,ref pending);Compare(text,"Classe térmica exigida",String.IsNullOrWhiteSpace(r.TripClass)||String.IsNullOrWhiteSpace(binding.RequiredTripClass)?(bool?)null:Same(r.TripClass,binding.RequiredTripClass),"Classe exigida="+binding.RequiredTripClass+". A classe não é obtida de In nem demonstra sozinha suportabilidade à partida.",ref fail,ref pending);Compare(text,"Relé térmico e faixa de ajuste",!String.IsNullOrWhiteSpace(r.OverloadReference)&&r.ThermalMinimumA>0&&r.ThermalMaximumA>0&&r.ThermalSettingA>0?(bool?)(r.ThermalSettingA>=r.ThermalMinimumA&&r.ThermalSettingA<=r.ThermalMaximumA):null,"Faixa "+r.ThermalMinimumA+"–"+r.ThermalMaximumA+" A; ajuste="+r.ThermalSettingA+" A.",ref fail,ref pending);
if(r.OverloadConnection!=OverloadConnection.InLine){pending=true;text.AppendLine("Pendente: só se verifica aqui relé em linha. Ligação dentro do triângulo ou não definida requer método próprio; não aplicar √3 automaticamente.");}else Compare(text,"Ajuste nominal em linha",binding.MotorRatedA>0&&r.ThermalSettingA>0?(bool?)(Math.Abs(r.ThermalSettingA-binding.MotorRatedA)<=1e-9*Math.Max(1,binding.MotorRatedA)):null,"Escopo nominal1:1 entre ajuste térmico e corrente de placa, sem fatores de serviço/condições especiais presumidos.",ref fail,ref pending);Compare(text,"Ajuste térmico ≤ Iz",r.ThermalSettingA>0&&row.CorrectedAmpacityA.HasValue?(bool?)(r.ThermalSettingA<=row.CorrectedAmpacityA.Value):null,"Sobrecorrente/energia e coordenação completa do cabo exigem seus próprios dados.",ref fail,ref pending);
if(r.Kind==MotorStarterKind.ContactorOverload)Compare(text,"Alimentação da bobina",r.ControlVoltageV>0&&binding.ControlVoltageV>0?(bool?)(r.ControlVoltageV==binding.ControlVoltageV&&r.ControlSupply==binding.ControlSupply):null,"Ficha="+r.ControlVoltageV+" V "+r.ControlSupply+"; comando="+binding.ControlVoltageV+" V "+binding.ControlSupply+".",ref fail,ref pending);
Compare(text,"Tipo de coordenação documentado",String.IsNullOrWhiteSpace(r.CoordinationType)||String.IsNullOrWhiteSpace(binding.RequiredCoordinationType)||String.IsNullOrWhiteSpace(r.AssemblyDocument)?(bool?)null:Same(r.CoordinationType,binding.RequiredCoordinationType),"Requisito="+binding.RequiredCoordinationType+"; documento="+r.AssemblyDocument+". Não deduzir tipo1/2 de curvas ou correntes individuais.",ref fail,ref pending);
if(r.ConditionalKA>0){string current=ProtectionConfiguration(c,r.ProtectionKind);bool known=current!=""&&String.Equals(current,r.RequiredProtectionConfiguration,StringComparison.OrdinalIgnoreCase);double? capacity=null,rated=null;if(r.ProtectionKind==StarterProtectionKind.PrimaryBreaker){string ignored;known=known&&c.Protection.BreakerSnapshot!=null&&BreakerSelection.Applicable(p,row,c.Protection.BreakerSnapshot,out ignored);capacity=c.Protection.BreakingCapacityKA;rated=c.BreakerA;}else if(r.ProtectionKind==StarterProtectionKind.SelectedFuse&&c.SwitchgearSelection!=null){var fuse=c.SwitchgearSelection.Rating;known=known&&fuse.IsFuse&&fuse.VoltageV==c.Voltage&&fuse.FrequencyHz==p.Frequency&&BreakerSelection.ValidTopology(row,fuse.Poles);capacity=fuse.BreakingKA;rated=fuse.RatedA;}Compare(text,"Proteção de curto do conjunto",known&&capacity.HasValue&&row.FaultOriginKA.HasValue?(bool?)(capacity.Value>=row.FaultOriginKA.Value&&r.ConditionalKA>=row.FaultOriginKA.Value):null,"Proteção="+r.ProtectionKind+"; limite condicional="+r.ConditionalKA+" kA; configuração exata do documento.",ref fail,ref pending);Compare(text,"Proteção suporta corrente nominal do motor",known&&rated.HasValue&&binding.MotorRatedA>0?(bool?)(rated.Value>=binding.MotorRatedA):null,"Comparação com placa, sem aplicar fator de demanda.",ref fail,ref pending);}else Compare(text,"Capacidade própria do disjuntor-motor",r.Kind==MotorStarterKind.ManualMotorBreaker&&r.StandaloneBreakingKA>0&&row.FaultOriginKA.HasValue?(bool?)(r.StandaloneBreakingKA>=row.FaultOriginKA.Value):null,"Contator/manobra com térmico não elimina curto; exigir associação documentada. Capacidade própria declarada="+r.StandaloneBreakingKA+" kA.",ref fail,ref pending);
if(c.DriveMotor!=null){pending=true;text.AppendLine("Pendente: conjunto na saída/associação com inversor exige avaliação específica; não aplicar diretamente este modelo de partida em linha ao PWM.");}if(new[]{r.Manufacturer,r.Reference,r.ControllerReference,r.Service,r.OverloadReference,r.TripClass,r.CoordinationType,r.Source,r.DataVersion,r.Conditions,r.AssemblyDocument}.Any(x=>x.StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase))){pending=true;text.AppendLine("Pendente: modelo ainda não preenchido; valores de exemplo não são evidência.");}text.AppendLine("Avaliação nominal de conjunto por dados declarados. Não autentica tabela nem prova aquecimento/aceleração, suportabilidade à partida, frequência de manobras, perda de fase, condições especiais, Ik máximo ou coordenação global. O conjunto adicional não altera potência, demanda, proteção primária ou curvas automaticamente.");return new MotorStarterEvaluation{Status=fail?"Não atende":pending?"Dados incompletos":"Atende comparações nominais",Detail=text.ToString(),NominalCalculatedA=nominal};}
static void Compare(StringBuilder text,string rule,bool? pass,string detail,ref bool fail,ref bool pending){if(!pass.HasValue)pending=true;else if(!pass.Value)fail=true;text.AppendLine((pass.HasValue?(pass.Value?"Atende":"Não atende"):"Pendente")+": "+rule+". "+detail);}
public static void Apply(Project p,Circuit c,MotorStarterBinding binding){binding.Validate();var result=Evaluate(p,Engineering.Analyze(p),c,binding);if(result.Status=="Não atende")throw new InvalidDataException("Nenhuma alteração: "+result.Detail);c.MotorStarterSelection=new MotorStarterBinding{Engine=binding.Engine,Rating=binding.Rating.Copy(),MotorRatedA=binding.MotorRatedA,MotorNameplateSource=binding.MotorNameplateSource,RequiredService=binding.RequiredService,RequiredTripClass=binding.RequiredTripClass,RequiredCoordinationType=binding.RequiredCoordinationType,RequiredPoles=binding.RequiredPoles,ControlVoltageV=binding.ControlVoltageV,ControlSupply=binding.ControlSupply};}
public static MotorStarterRating Template(Project p,Circuit c,MotorStarterKind kind){var protection=c.SwitchgearSelection!=null&&c.SwitchgearSelection.Rating.IsFuse?StarterProtectionKind.SelectedFuse:StarterProtectionKind.PrimaryBreaker;string key=ProtectionConfiguration(c,protection);if(key=="")throw new InvalidDataException("Selecione disjuntor primário ou fusível identificado antes de gerar este modelo.");return new MotorStarterRating{Kind=kind,Manufacturer="PREENCHER fabricante",Reference="PREENCHER conjunto",ControllerReference="PREENCHER controlador",Service="PREENCHER serviço",VoltageV=c.Voltage,FrequencyHz=p.Frequency,Poles=c.Protection.BreakerSnapshot!=null?c.Protection.BreakerSnapshot.RequiredPoles:c.SwitchgearSelection.RequiredPoles,RatedMotorA=Math.Max(1,NominalCurrent(c)),OverloadReference="PREENCHER térmico",TripClass="PREENCHER classe",ProtectionKind=protection,ConditionalKA=.001,RequiredProtectionConfiguration=key,CoordinationType="PREENCHER tipo de coordenação",AssemblyDocument="PREENCHER documento e limites",Source="PREENCHER fonte",DataVersion="PREENCHER versão",Conditions="PREENCHER condições; substituir valores de exemplo pela ficha"};}
static string Key(MotorStarterRating r){return String.Join("\0",new[]{r.Kind.ToString(),r.Manufacturer.Trim(),r.Reference.Trim(),r.ControllerReference.Trim(),r.OverloadReference.Trim(),r.Service.Trim(),r.TripClass.Trim(),r.Poles.ToString(),r.VoltageV.ToString("R",CultureInfo.InvariantCulture),r.FrequencyHz.ToString("R",CultureInfo.InvariantCulture),r.RatedMotorA.ToString("R",CultureInfo.InvariantCulture),r.ThermalSettingA.ToString("R",CultureInfo.InvariantCulture),r.RequiredProtectionConfiguration,r.CoordinationType.Trim(),r.ControlVoltageV.ToString("R",CultureInfo.InvariantCulture),r.ControlSupply.ToString()});}
public static List<MotorStarterRating> Import(string file){return ComponentCsv.Import<MotorStarterRating>(file,Header,r=>r.Validate(),Key);}public static void Export(IEnumerable<MotorStarterRating> rows,string file){ComponentCsv.Export(rows,file,Header,r=>r.Validate(),Key);}
}
